const standardOrder = { netCents: 2599, membership: "standard", express: false, discountCents: 0 };

test("a standard member earns one point per whole dollar, ignoring leftover cents", () => {
  assert.equal(loyaltyPoints(standardOrder), 25);
});

test("a silver member earns double points", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, membership: "silver" }), 50);
});

test("a gold member earns triple points", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, membership: "gold" }), 75);
});

test("express shipping adds a 50 point bonus", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, express: true }), 75);
});

test("a discount halves a silver member's points including the bonus", () => {
  const order = { ...standardOrder, membership: "silver", express: true, discountCents: 500 };
  assert.equal(loyaltyPoints(order), 50);
});

test("a discount halves points rounding down to a whole number", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, netCents: 2300, discountCents: 500 }), 11);
});

test("a gold member keeps all points when a discount was taken", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, membership: "gold", discountCents: 500 }), 75);
});

test("an order under one dollar earns no points", () => {
  assert.equal(loyaltyPoints({ ...standardOrder, netCents: 99 }), 0);
});

test("a negative net amount is rejected", () => {
  assert.throws(() => loyaltyPoints({ ...standardOrder, netCents: -1 }), /amount/);
});
EOF
